// Gerado por scripts/build.js. Não editar no n8n: editar /src e /scripts e voltar a enviar.

// ===== src/config.js =====
/**
 * Configuração central do chatbot.
 *
 * É o único sítio onde se mudam limites, modelo, links e textos de
 * contacto. O scripts/build.js copia este ficheiro para os Code nodes
 * que precisam dele; nos workflows nunca se editam estes valores à mão.
 *
 * Tudo o que está aqui é público (vai para os exports em /workflows).
 * Segredos ficam nas credenciais do n8n, nunca aqui.
 */
const CONFIG = {
  schemaVersion: 1,

  // Modelo escolhido pela comparação de 2026-10-18 (ver docs/DECISIONS.md), via
  // OpenRouter. Preços em USD por 1M tokens: confirmar no OpenRouter antes de
  // cada eval, porque só servem para estimar o custo (o valor real é o do
  // OpenRouter).
  modelo: {
    id: 'anthropic/claude-haiku-5.5',
    precoEntradaUsdPorMilhao: 0.1,
    precoSaidaUsdPorMilhao: 0.5,
    // Teto da resposta do modelo, incluindo o raciocínio interno que alguns
    // modelos (o Haiku 5.5, por exemplo) fazem antes de escrever: com 700, o
    // raciocínio comia parte do teto e a resposta saía cortada ou vazia. O
    // tamanho visível é limitado por limites.respostaMaxChars.
    maxTokens: 2000,
    timeoutMs: 25000,
  },
  usdParaEur: 0.92,

  memoriaJanela: 12,

  limites: {
    mensagemMaxChars: 1000,
    respostaMaxChars: 1200,
    sessaoPorMinuto: 6,
    sessaoPorDia: 60,
    globalPorMinuto: 30,
    globalPorDia: 1500,
    // Kill switch: teto do custo estimado do dia, por canal; cada canal só
    // conta o que gastou. Os evals não podem fechar o chat aos visitantes, e
    // juntos (~1,75 USD) ficam abaixo do teto de 2 USD/dia da chave do
    // OpenRouter. Canal que não esteja aqui tem teto 0: fica fechado.
    custoDiarioMaxEur: { site: 1, eval: 0.6 },
    quarentenasMaxPorSessao: 3,
    quarentenaBloqueioMinutos: 60,
    ctasMaxPorConversa: 2,
  },

  // Fuso usado para "por dia" (contadores e kill switch).
  fusoHorario: 'Europe/Lisbon',

  site: {
    origens: ['https://nautica-ai-agency.com', 'https://www.nautica-ai-agency.com'],
    emailContacto: 'hello@nautica-ai-agency.com',
  },

  cal: {
    url: 'https://cal.com/nautica-ai-xuismz/30min',
    textoLink: 'marcar a chamada de diagnóstico',
  },

  // Links que podem aparecer numa resposta. Tudo o resto é removido.
  linksPermitidos: [
    { host: 'nautica-ai-agency.com', prefixo: '/' },
    { host: 'www.nautica-ai-agency.com', prefixo: '/' },
    { host: 'cal.com', prefixo: '/nautica-ai-xuismz/' },
    { host: 'app.cal.com', prefixo: '/nautica-ai-xuismz/' },
  ],

  // Marcador que o agente escreve onde quer a chamada à ação.
  // O pós-processamento troca-o pelo link do Cal.com pré-preenchido.
  marcadorCta: '[[MARCAR]]',

  motivosHandoff: ['lead_qualificado', 'pede_humano', 'reclamacao', 'outro'],
  // Reservado ao aviso automático do tool-registar-lead: se o agente o pedir,
  // fica 'outro' (senão, um aviso prematuro sem contacto bloquearia o
  // automático, que é único por conversa e motivo).
  motivoAutomatico: 'lead_qualificado',

  // Leads com email destes domínios ficam só no Postgres (estado 'teste'):
  // sem Notion nem Discord. Evals e visitantes que escrevem emails de exemplo.
  leadsTeste: {
    dominios: ['exemplo.pt', 'exemplo.com', 'example.com', 'example.org', 'example.net', 'teste.pt', 'test.com'],
  },

  // Base de conhecimento: ficheiro no Google Drive lido pelo kb-sync. Pode ser
  // um .md (descarregado tal como está) ou um Google Doc (exportado em
  // Markdown). Atualizar o .md com "Gerir versões → Carregar nova versão",
  // para o ID não mudar.
  kb: {
    driveFileId: '1hObVLQh_YVhpTN6THlxmnMuHYmII-w3T', // Base_Conhecimento_Chatbot_Nautica.md
  },

  notion: {
    versaoApi: '2022-06-28',
    // Base onde o bot escreve (dentro de "CRM Clientes").
    chatbotSite: '898aca1a-b806-438f-8072-1fcaaab208f0',
    // CRMs dos comerciais: SÓ LEITURA, para saber se o contacto já existe.
    // tipoTelefone: tipo da propriedade Telefone em cada base.
    crms: [
      { nome: 'Clientes Site', id: 'b6f1d968-06dc-48fc-ac7b-fff78e32afe1', tipoTelefone: 'phone_number' },
      { nome: 'CRM Nautica AI', id: '96af931a-07df-452c-bb9b-6160712ade3c', tipoTelefone: 'rich_text' },
    ],
  },
};

// ===== src/guardas.js =====
/**
 * Guardas determinísticas, aplicadas antes de qualquer chamada ao LLM.
 *
 * JavaScript puro, sem require: o scripts/build.js copia este ficheiro
 * (até à linha de corte) para os Code nodes. Todas as funções recebem
 * a configuração como argumento, para se poderem testar sem o n8n.
 *
 * Duas famílias:
 *  - tráfego (sub-workflow guard-trafego, chamado pelos adaptadores públicos);
 *  - conteúdo e custo (chat-core, corre em todos os canais, incluindo o eval).
 */

/** Motivos de bloqueio. São também os valores gravados em turns.guarda. */
const MOTIVOS_BLOQUEIO = [
  'sessao_invalida',
  'sessao_bloqueada',
  'mensagem_vazia',
  'mensagem_longa',
  'quarentena',
  'limite_sessao',
  'teto_global',
  'kill_switch_custo',
  'pedido_invalido', // não é uma mensagem de texto (ex.: ficheiros enviados diretamente ao webhook)
  'sem_kb', // não há base de conhecimento ativa: o agente não responde sem ela
];

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

/** Limpa o texto recebido: NFC, sem caracteres de controlo, espaços arrumados. */
function normalizarTexto(texto) {
  if (texto === null || texto === undefined) return '';
  return String(texto)
    .normalize('NFC')
    .replace(/\r\n?/g, '\n')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F​-‏‪-‮⁠-⁤﻿]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/** Minúsculas e sem acentos, para as regras não dependerem da grafia. */
function paraComparar(texto) {
  return String(texto)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function validarSessionId(id) {
  return typeof id === 'string' && UUID_RE.test(id);
}

/*
 * Regras de quarentena. Cada regra tem um id (fica registado no turno) e
 * corre sobre o texto sem acentos e em minúsculas, exceto as marcadas com
 * `original: true`.
 *
 * Critério: apanhar pedidos dirigidos ao bot (as instruções dele, os
 * segredos dele, mudar o papel dele), não temas. Um visitante pode
 * perguntar como guardamos as credenciais dos clientes; isso não é ataque.
 */
const REGRAS_INJECAO = [
  {
    id: 'ignorar_instrucoes',
    // "Regras" sozinho não chega ("posso ignorar as regras do IVA?"): só
    // conta com um qualificador que aponte para as instruções do bot.
    re: /\b(ignor[ae]\w*|esquec[ea]\w*|desconsider[ae]\w*|ignore|disregard|forget)\b.{0,40}(\b(instruc\w*|instructions?|prompts?)\b|\b(regras|ordens|indicac\w*|rules)\b.{0,20}\b(anteriores|acima|iniciais|previous|above|prior|que (te|lhe) deram)\b|\b(tudo|everything)\b.{0,15}\b(acima|anterior|above|before)\b)/,
  },
  {
    id: 'pedir_prompt',
    re: /\b(system ?prompt|prompt (do|de) sistema|prompt inicial|initial prompt|(instrucoes|regras|orientacoes) (do sistema|iniciais|internas|originais|secretas|que (te|lhe) (deram|foram dadas)|que recebeste)|your (instructions|rules|system message)|developer message)\b/,
  },
  {
    id: 'repetir_contexto',
    re: /\b(repete|repita|reescreve|reescreva|copia|copie|imprime|imprima|mostra|mostre|repeat|print|output|show)\b.{0,30}\b(tudo|todo o texto|o texto|everything|all|the text|the words)\b.{0,20}\b(acima|anterior|antes disto|above|before this)\b/,
  },
  {
    // Só segredos *do bot* (possessivo antes ou depois): "a tua API key",
    // "a password do vosso n8n". "Credenciais dos nossos clientes" passa.
    id: 'pedir_segredos',
    re: (() => {
      const dono = '(tua|teu|tuas|teus|vossa|vosso|vossas|vossos|your|do bot|do servidor|do n8n|da openai|do openrouter)';
      const segredo =
        '(api[ _-]?keys?|chaves? (da|de) api|chaves? secretas?|tokens?|passwords?|palavras?[- ]passe|senhas?|credenciais|credentials|secrets?|variaveis de ambiente|environment variables|\\.env)';
      return new RegExp(`\\b${dono}\\b\\W+(\\w+\\W+){0,3}${segredo}\\b|\\b${segredo}\\W+(\\w+\\W+){0,3}${dono}\\b`);
    })(),
  },
  {
    id: 'mudar_papel',
    re: /\b(a partir de agora (es|seras|vais ser|passas a ser|ages)|finge (que es|ser)|faz de conta que es|comporta-te como|you are now|from now on you|act as|pretend (to be|you are)|roleplay|jailbreak|modo (dev|desenvolvedor|developer|sem restricoes)|developer mode|do anything now)\b/,
  },
  {
    id: 'marcadores_sistema',
    original: true,
    re: /(<\|?\s*(system|im_start|im_end|endoftext)\s*\|?>|\[\/?(system|inst)\]|<\/?system>|^\s*#{1,6}\s*(system|instructions?)\s*:?\s*$)/im,
  },
  {
    // Base64 ou semelhante: um bloco longo sem espaços que mistura
    // maiúsculas, minúsculas e dígitos (texto repetido não conta).
    id: 'bloco_codificado',
    original: true,
    testa: (t) =>
      (t.match(/[A-Za-z0-9+/]{120,}={0,2}/g) || []).some((b) => /[A-Z]/.test(b) && /[a-z]/.test(b) && /\d/.test(b)),
  },
];

/** Devolve as regras de quarentena que o texto aciona (lista vazia = limpo). */
function detetarInjecao(texto) {
  const original = String(texto || '');
  const comparavel = paraComparar(original);
  return REGRAS_INJECAO.filter((r) => {
    const alvo = r.original ? original : comparavel;
    return r.testa ? r.testa(alvo) : r.re.test(alvo);
  }).map((r) => r.id);
}

/**
 * Guardas de conteúdo (chat-core). Corre em todos os canais.
 * `estado.quarentenasRecentes`: quarentenas da sessão na janela de bloqueio.
 */
function avaliarConteudo(payload, cfg, estado) {
  const quarentenas = (estado && estado.quarentenasRecentes) || 0;
  const texto = normalizarTexto(payload && payload.texto);
  const bloqueio = (motivo, regras) => ({ permitido: false, motivo, regras: regras || [], texto });

  if (!validarSessionId(payload && payload.session_id)) return bloqueio('sessao_invalida');
  if (quarentenas >= cfg.limites.quarentenasMaxPorSessao) return bloqueio('sessao_bloqueada');
  if (!texto) return bloqueio('mensagem_vazia');
  if (texto.length > cfg.limites.mensagemMaxChars) return bloqueio('mensagem_longa');

  const regras = detetarInjecao(texto);
  if (regras.length) return bloqueio('quarentena', regras);

  return { permitido: true, motivo: null, regras: [], texto };
}

/**
 * Guardas de tráfego (guard-trafego). As contagens já incluem o pedido
 * atual, porque o contador é incrementado antes de se avaliar.
 * O teto global vem primeiro: é a proteção real, porque o session_id é
 * gerado no cliente e pode ser rodado.
 */
function avaliarTrafego(contagens, cfg) {
  const l = cfg.limites;
  const c = contagens || {};
  if ((c.globalMin || 0) > l.globalPorMinuto || (c.globalDia || 0) > l.globalPorDia) {
    return { permitido: false, motivo: 'teto_global' };
  }
  if ((c.sessaoMin || 0) > l.sessaoPorMinuto || (c.sessaoDia || 0) > l.sessaoPorDia) {
    return { permitido: false, motivo: 'limite_sessao' };
  }
  return { permitido: true, motivo: null };
}

/** Teto diário do canal; sem teto configurado é 0 (canal fechado). */
function tetoCustoDiario(canal, cfg) {
  return Number(cfg.limites.custoDiarioMaxEur[canal]) || 0;
}

/** Kill switch: bloqueia quando o custo estimado do dia no canal chega ao teto. */
function avaliarCusto(custoHojeEur, canal, cfg) {
  if (Number(custoHojeEur || 0) >= tetoCustoDiario(canal, cfg)) {
    return { permitido: false, motivo: 'kill_switch_custo' };
  }
  return { permitido: true, motivo: null };
}

/*
 * Estimativa de tokens. O AI Agent do n8n não passa o consumo real aos
 * nós seguintes, por isso o custo registado é estimado (~4 caracteres por
 * token). O valor real fica no painel do OpenRouter.
 */
function estimarTokens(texto) {
  return Math.ceil(String(texto || '').length / 4);
}

/**
 * Consumo estimado de um turno do agente. Cada chamada a uma tool é mais
 * uma ida ao modelo, que volta a receber o contexto inteiro (sistema + KB +
 * histórico + mensagem) e os passos anteriores.
 * `c`: { sistemaChars, historicoChars, textoChars, respostaChars,
 *        passos: [{ entrada, saida }] }  (entrada/saida das tools, em texto)
 */
function estimarConsumo(c, cfg) {
  const passos = c.passos || [];
  const base = (c.sistemaChars || 0) + (c.historicoChars || 0) + (c.textoChars || 0);
  const iteracoes = 1 + passos.length;
  let acumulado = 0;
  let entradaChars = 0;
  let saidaChars = c.respostaChars || 0;
  for (let i = 0; i < iteracoes; i++) {
    entradaChars += base + acumulado;
    if (i < passos.length) {
      const e = String(passos[i].entrada || '').length;
      const s = String(passos[i].saida || '').length;
      saidaChars += e;
      acumulado += e + s;
    }
  }
  const tokensEntrada = Math.ceil(entradaChars / 4);
  const tokensSaida = Math.ceil(saidaChars / 4);
  return { tokensEntrada, tokensSaida, custoEur: estimarCustoEur(tokensEntrada, tokensSaida, cfg) };
}

function estimarCustoEur(tokensEntrada, tokensSaida, cfg) {
  const m = cfg.modelo;
  const usd = (tokensEntrada * m.precoEntradaUsdPorMilhao + tokensSaida * m.precoSaidaUsdPorMilhao) / 1e6;
  return Math.round(usd * cfg.usdParaEur * 1e6) / 1e6;
}

/** Resposta fixa e útil para cada bloqueio. Nunca chama o LLM. */
function respostaFixa(motivo, cfg) {
  const cal = `[${cfg.cal.textoLink}](${cfg.cal.url})`;
  const email = cfg.site.emailContacto;
  const textos = {
    sessao_invalida: 'Não consegui ler esta conversa. Recarregue a página e tente outra vez.',
    sessao_bloqueada: `Esta conversa foi pausada. Se quiser falar connosco, pode ${cal} ou escrever para ${email}.`,
    mensagem_vazia: 'Não recebi nenhuma mensagem. Em que posso ajudar?',
    mensagem_longa: `A mensagem é um pouco longa para este chat. Consegue resumi-la em poucas frases? Se preferir explicar com calma, pode ${cal}.`,
    quarentena: `Não posso ajudar com esse pedido. Posso responder a perguntas sobre os serviços da Náutica AI ou ajudar a ${cal}.`,
    limite_sessao: `Está a enviar mensagens muito depressa. Aguarde um minuto e tente outra vez. Se preferir, pode ${cal}.`,
    teto_global: `De momento o assistente não está disponível. Pode ${cal} ou escrever para ${email}.`,
    kill_switch_custo: `De momento o assistente não está disponível. Pode ${cal} ou escrever para ${email}.`,
    pedido_invalido: `Este chat só aceita mensagens de texto. Se precisar de nos enviar um ficheiro, escreva para ${email}.`,
    sem_kb: `Desculpe, não consigo responder agora. Pode ${cal} ou escrever para ${email} e a nossa equipa responde-lhe.`,
    fallback: `Desculpe, não consegui responder agora. Pode ${cal} ou escrever para ${email} e a nossa equipa responde-lhe.`,
  };
  return textos[motivo] || textos.fallback;
}

// ===== src/validacoes.js =====
/**
 * Validação e normalização dos dados que o agente passa às tools
 * (registar_lead e avisar_humano).
 *
 * JavaScript puro, sem require, copiado para os Code nodes pelo build.
 * Os nomes não podem colidir com os dos outros ficheiros de /src, porque
 * o build pode juntar vários no mesmo Code node.
 */

const LIMITES_CAMPOS_LEAD = {
  nome: 120,
  empresa: 160,
  setor: 120,
  problema: 2000,
  resumo: 4000,
};

/** Texto livre vindo do LLM: sem controlo, espaços arrumados, cortado ao limite. */
function limparCampo(valor, max) {
  if (valor === null || valor === undefined) return null;
  const limpo = String(valor)
    .normalize('NFC')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (!limpo) return null;
  return limpo.length > max ? limpo.slice(0, max).trim() : limpo;
}

function validarEmail(valor) {
  if (!valor) return { valido: false, email: null };
  const email = String(valor).trim().toLowerCase().replace(/^mailto:/, '');
  const [local, dominio, ...resto] = email.split('@');
  const valido =
    resto.length === 0 &&
    !!local &&
    !!dominio &&
    email.length <= 254 &&
    local.length <= 64 &&
    /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/.test(local) &&
    !/^\.|\.$|\.\./.test(local) &&
    /^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/.test(dominio);
  return { valido, email: valido ? email : null };
}

/**
 * Normaliza para E.164. Sem indicativo, assume Portugal (+351) quando o
 * número tem 9 dígitos e começa por 2, 3 ou 9.
 */
function normalizarTelefone(valor) {
  if (!valor) return { valido: false, e164: null };
  let s = String(valor).trim().replace(/[\s.\-()/]/g, '');
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (!/^\+?\d+$/.test(s)) return { valido: false, e164: null };

  let e164 = null;
  if (s.startsWith('+')) {
    if (s.startsWith('+351')) {
      if (/^\+351[239]\d{8}$/.test(s)) e164 = s;
    } else if (/^\+[1-9]\d{7,14}$/.test(s)) {
      e164 = s;
    }
  } else if (/^[239]\d{8}$/.test(s)) {
    e164 = '+351' + s;
  }
  return { valido: !!e164, e164 };
}

/**
 * Valida o pedido do registar_lead. Campos inválidos ficam a null e
 * são reportados em `avisos`, mas o lead é sempre gravado no Postgres:
 * só a sincronização com o Notion exige um contacto válido.
 */
function validarLead(entrada) {
  const e = entrada || {};
  const avisos = [];
  const email = validarEmail(e.email);
  const telefone = normalizarTelefone(e.telefone);
  if (e.email && !email.valido) avisos.push('email_invalido');
  if (e.telefone && !telefone.valido) avisos.push('telefone_invalido');

  const lead = {
    nome: limparCampo(e.nome, LIMITES_CAMPOS_LEAD.nome),
    empresa: limparCampo(e.empresa, LIMITES_CAMPOS_LEAD.empresa),
    setor: limparCampo(e.setor, LIMITES_CAMPOS_LEAD.setor),
    problema: limparCampo(e.problema, LIMITES_CAMPOS_LEAD.problema),
    resumo: limparCampo(e.resumo, LIMITES_CAMPOS_LEAD.resumo),
    email: email.email,
    telefone: telefone.e164,
  };
  return { lead, contactoValido: email.valido || telefone.valido, avisos };
}

/**
 * Motivo do avisar_humano: enum fechado, para a idempotência funcionar. O
 * motivo automático (lead com contacto) só pode vir do próprio fluxo
 * (origem 'automatico'); pedido pelo agente, passa a 'outro'.
 */
function validarMotivo(motivo, cfg, origem) {
  const m = String(motivo || '').trim().toLowerCase();
  if (!cfg.motivosHandoff.includes(m)) return 'outro';
  if (m === cfg.motivoAutomatico && origem !== 'automatico') return 'outro';
  return m;
}

// ===== código deste nó =====
const e = $input.first().json;
if (!validarSessionId(e.session_id)) return [{ json: { valido: false } }];
return [{
  json: {
    valido: true,
    session_id: e.session_id,
    motivo: validarMotivo(e.motivo, CONFIG, e.origem),
    resumo: limparCampo(e.resumo, LIMITES_CAMPOS_LEAD.resumo) || '(sem resumo)',
  },
}];

// Gerado por scripts/build.js. Não editar no n8n: editar /src e /scripts e voltar a enviar.

// ===== src/mensagens.js =====
/**
 * Mensagens para o Discord (leads e alertas internos).
 *
 * Texto vindo do visitante é neutralizado: um "@everyone" escrito no chat
 * não pode notificar o canal inteiro. O Discord corta acima de 2000
 * caracteres, por isso tudo é limitado aqui.
 *
 * JavaScript puro, sem require, copiado para os Code nodes pelo build.
 */

const LIMITE_DISCORD = 2000;

const ROTULOS_MOTIVO = {
  lead_qualificado: 'Lead qualificado',
  pede_humano: 'Pede para falar com uma pessoa',
  reclamacao: 'Reclamação',
  outro: 'Outro',
};

/** Neutraliza menções e marcação que o visitante possa ter escrito. */
function semMencoes(valor) {
  return String(valor === null || valor === undefined ? '' : valor)
    .replace(/@(everyone|here)/gi, '@​$1')
    .replace(/<(@[!&]?|#)(\d+)>/g, '<$1​$2>')
    .replace(/```/g, "'''");
}

function cortar(texto, max) {
  const t = String(texto);
  return t.length > max ? t.slice(0, max - 1) + '…' : t;
}

/**
 * Aviso de handoff para o canal de leads.
 * `dados`: { motivo, resumo, session_id, nome, empresa, setor, email,
 *            telefone, problema, crm_existente, crm_paginas, notion_page_id }
 */
function mensagemHandoff(dados) {
  const d = dados || {};
  const linhas = [`**Chatbot do site — ${ROTULOS_MOTIVO[d.motivo] || ROTULOS_MOTIVO.outro}**`];

  const quem = [d.nome, d.empresa, d.setor].filter(Boolean).map(semMencoes).join(' · ');
  if (quem) linhas.push(quem);
  const contacto = [d.email, d.telefone].filter(Boolean).map(semMencoes).join(' · ');
  linhas.push(contacto ? `Contacto: ${contacto}` : 'Contacto: ainda não deixou');

  if (d.crm_existente) {
    const paginas = (d.crm_paginas || []).map((p) => `${p.crm} (<${p.url}>)`).join(', ');
    linhas.push(`⚠️ Já existe no CRM dos comerciais: ${paginas || 'sim'}`);
  }
  if (d.problema) linhas.push(`**Problema:** ${cortar(semMencoes(d.problema), 400)}`);

  const rodape = [];
  if (d.notion_page_id) rodape.push(`Notion: <https://www.notion.so/${String(d.notion_page_id).replace(/-/g, '')}>`);
  rodape.push(`Sessão: ${semMencoes(d.session_id)}`);

  const fixo = linhas.join('\n') + '\n**Resumo:** ' + '\n' + rodape.join(' · ');
  const espaco = LIMITE_DISCORD - fixo.length;
  const resumo = cortar(semMencoes(d.resumo || '(sem resumo)'), Math.max(espaco, 50));

  return cortar([...linhas, `**Resumo:** ${resumo}`, rodape.join(' · ')].join('\n'), LIMITE_DISCORD);
}

/** Alerta de base de conhecimento inválida (canal de erros). */
function mensagemKbInvalida(erros, hash) {
  const lista = (erros || []).map((e) => `• ${e}`).join('\n');
  return cortar(
    '**kb-sync: a versão nova da base de conhecimento NÃO foi ativada.**\n' +
      'O bot continua com a versão anterior. Corrigir o Google Doc:\n' +
      lista +
      `\n(hash ${String(hash || '').slice(0, 12)})`,
    LIMITE_DISCORD
  );
}

